describe('Navigation Bar Active Menu Item Highlighting', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should highlight active menu item in navigation bar', () => {
    // Navigate to the home page
    cy.get('[data-testid="nav-link-home"]').click();

    // Verify home page is loaded
    cy.get('[data-testid="page-title"]').should('contain', 'Home');

    // Verify home menu item is highlighted
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'color', 'rgb(255, 255, 255)');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'font-weight', 'bold');

    // Navigate to the about page
    cy.get('[data-testid="nav-link-about"]').click();

    // Verify about page is loaded
    cy.get('[data-testid="page-title"]').should('contain', 'About');

    // Verify about menu item is now highlighted
    cy.get('[data-testid="nav-link-about"]').should('have.css', 'color', 'rgb(255, 255, 255)');
    cy.get('[data-testid="nav-link-about"]').should('have.css', 'font-weight', 'bold');

    // Navigate back to home
    cy.get('[data-testid="nav-link-home"]').click();

    // Verify home menu item is highlighted again
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'color', 'rgb(255, 255, 255)');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'font-weight', 'bold');
  });

  it('should not highlight menu item when page is not active', () => {
    // Navigate to a non-existent page
    cy.get('[data-testid="nav-link-contact"]').click();

    // Verify page does not load (error message appears)
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify contact menu item is not highlighted
    cy.get('[data-testid="nav-link-contact"]').should('not.have.css', 'color', 'rgb(255, 255, 255)');
    cy.get('[data-testid="nav-link-contact"]').should('not.have.css', 'font-weight', 'bold');

    // Navigate back to home
    cy.get('[data-testid="nav-link-home"]').click();

    // Verify home menu item is highlighted
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'color', 'rgb(255, 255, 255)');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'font-weight', 'bold');
  });
});
